"use strict";let StockTrackingComponent=new function(){let mThis=this;this.title_prop='Stock Tracking';this.base_url=$('#__base_url').val();this.self=$('#_main_stockTrackingComponent');this.btnNew=$('#_stk_btnNew');this.elSearchItem=$('#_stk_search');this.elFilter_category=$('#_stk_filter_category');this.elFilter_stock_class=$('#_stk_filter_class');this.elFilter_loc_warehouse=$('#_stk_filter_warehouse');this.elFilter_loc_block=$('#_stk_filter_block');this.dlgFilter=$('#_stk_dlg_filter');this.btnReceiveStock=$('#_stk_btnNew_ReceiveStock');this.tblItems=$('#_stk_tblItems');this.icon_url=[VSUtil.asset_url(),'/images/icons'].join('');this.col_titles={"No.":"No.","Code":"Code","Name":"Name","Group":"Group","Category":"Category","SKU":"SKU","Qty":"Quantity","Quantity":"Quantity","Action":"Action"};this.prepareOptions=(onFinish)=>{vsapi.call(`${main_view.base_url}/api/inventory/settings/stock-tracking-options`,null).then(res=>{if(res.status_code===200){let d=StringSanitizer.sanitizeObject(res.data);onFinish(d);}});}
this.displayVariances=(detail_tr,appt_id=0)=>{let div_wrapper=detail_tr.find('div.expandable-row-container');div_wrapper.html('<div class="animation-line" style="height:2px;margin:0;"></div>');let p={'id':appt_id};window.vsapi.call(`${main_view.base_url}/api/inventory/item-details`,p,'POST',false).then((res)=>{let html=null;if(res.status_code===200){let d=StringSanitizer.sanitizeObject(res.data);d.patient_code=d.patient_code?d.patient_code:'N.A.';d.consultant_name=d.consultant_name?d.consultant_name:'Any';let tr=detail_tr.prev();tr.find('.client-name').text(d.client_name);tr.find('.client-code').text(d.patient_code);html=`<div data-apptid="${d.id}" data-leadid="${d.lead_id}" data-statusid="${d.status_id}" class="appt-info-wrapper shadow-lg d-flex" style="width:100%;">
                    <div class="thumbnail-wrapper">
                    <img src="${mThis.icon_url}/client-girl.png" class="profile-thumbnail">
                    </div>

                    <div class="d-flex" style="width:100%">
                            <div style="width:50%"> 
                            </div>
                            <div style="width:50%">
                            </div>
                    </div>
                </div>`;}else{html=`<div class="expanded-row-error">${error_message}</div>`;}
div_wrapper.html(html);});}
this.trans_title=(title_prop='undefined')=>{return(mThis.col_titles[title_prop]||'undefined');}
this.setLanguage=()=>{if(LocaleManager.lang!==mThis.lang){for(let prop in mThis.col_titles){mThis.col_titles[prop]=LocaleManager.trans(prop,'items',LocaleManager.lang);}
mThis.lang=LocaleManager.lang;}}
this.init=()=>{this.expandableConfig=new ExpandableRowConfig('_stk_tblItems',{'dontExpandByClickingOn':['tbody-stock-items','lnk-item-category','btn-group-action','btn-group-modify','btn-group-delete','btn-group-print'],'onOpen':(container,detail_tr,parent_tr)=>{let qtr=$(parent_tr);let group_id=qtr.data('id');mThis.createExpandedPanelContent($(detail_tr),{'group_id':group_id});}});mThis.dlgFilter.on('click',(e)=>{e.preventDefault();let op={onClose:(e)=>{if(e){mThis.displayItemGroups(e);}}};FilterDialog.show(op);});mThis.btnReceiveStock.on('click',(e)=>{e.preventDefault();let op={onClose:(e)=>{if(e){}}};ReceiveStokeDialog.show(op);});mThis.btnNew.on('click',(e)=>{let op={onClose:(e)=>{if(e){mThis.displayItemGroups();}}};ItemDialog.show(op);});mThis.elFilter_category.on('change',(e)=>{e.preventDefault();mThis.displayItemGroups();});mThis.elFilter_stock_class.on('change',(e)=>{e.preventDefault();mThis.displayItemGroups();});mThis.tblItems.on('click','a.btn-group-modify',function(e){let item_id=$(this).data("id");let op={id:item_id,onClose:(e)=>{if(e){mThis.displayItemGroups();}}};ItemDialog.show(op);});mThis.tblItems.on('click','a.btn-group-delete',function(e){let item_id=$(this).data("id");cv_interact.confirm(`Delete this product?`,{title:"Delete Product",context:"delete"},(yes)=>{if(yes){let p={"id":item_id};vsapi.call(`${main_view.base_url}/api/inventory/delete-item`,p).then(res=>{if(res.status_code===200){mThis.displayItemGroups();}else cv_interact.error(res.error_message);});}});});mThis.elSearchItem.on('keyup',(e)=>{let d=mThis.elSearchItem.val();if(!d||d.length>2||e.keyCode===13)mThis.displayItemGroups();});}
this.createExpandedPanelContent=(detail_tr,options)=>{let group_id=options.group_id;let div_wrapper=detail_tr.find('div.expandable-row-container');div_wrapper.html('<div class="animation-line" style="height:2px;margin:0;"></div>');let p={'group_id':group_id};window.vsapi.call(`${main_view.base_url}/api/inventory/stock/group-items`,p,'POST',false).then((res)=>{let html=null;if(res.status_code===200){let items=StringSanitizer.sanitizeObject(res.data);html=[`<div class="stock-items-panel">`,`<table class="w-100 inner-item-table header-uppercase">`,`<thead><tr>`,`<th>Item Code</th>`,`<th>Name</th>`,`<th>Desciption</th>`,`<th>Qty</th>`,`<th>Last Updated</th>`,`</tr></thead>`,`<tbody class="tbody-stock-items">`,mThis.createRowItems(items),`</tbody>
                        </table>`,`</div>`].join('');}else{html=`<div class="expanded-row-error">${res.error_message}</div>`;}
div_wrapper.html(html);});}
this.createRowItems=(items)=>{let html="";(items||[]).map(t=>{let sku=t.sku;if(t.qty>1&&sku)sku=[sku,'s'].join('');let qty=[t.qty?t.qty:0,` `,sku].join('');let inner_html=`<td>${t.code}</td><td>${t.name}</td> <td>${t.description ? t.description : "NA"}</td> <td>${qty}</td><td>${t.last_updated ? t.last_updated : "NA"}</td>`;html=[html,`<tr data-itemid="`,t.id,`">`,inner_html,`</tr>`].join('');});return html;}
this.displayItemGroups=(options,onFinish=null)=>{if(!options)options={};mThis.setLanguage();let p={'search_value':mThis.elSearchItem.val(),'category_id':mThis.elFilter_category.val(),'stock_class_code':mThis.elFilter_stock_class.val(),'warehouse_id':options.warehouse_id,'block_id':options.block,'group_id':options.group_id};window.vsapi.call(`${mThis.base_url}/api/inventory/stock/group-list`,p,'POST',null).then((result)=>{let data=[];if(result.status_code===200)data=result.data;if(mThis.table){mThis.tblItems.DataTable().clear().destroy();mThis.tblItems.empty();mThis.table=null;}
data=StringSanitizer.sanitizeObject(data,null);let cnt=1;let my_columns=[{title:mThis.trans_title("No."),data:()=>{return cnt;}},{title:mThis.trans_title("Code"),data:"code"},{data:"name",title:mThis.trans_title('Name')},{title:mThis.trans_title('Category'),data:(data,a,b)=>{return[`<span class="fw-normal d-block lnk-item-category"><a data-gid="${data.id}" data-catid="${data.category_id}" href="javasvript:void(0)">`,data.category,`</a></span>`,`<span class="text-secondary">`,data.detail_type,`</span>`].join('');}},{title:mThis.trans_title('Quantity'),data:(data,a,b)=>{let sku=data.sku;if(data.qty>1&&sku)sku=[sku,'s'].join('');return[data.qty?Number(data.qty):0,' ',sku].join('');}},{title:mThis.trans_title('Action'),data:function(item,a,b){return[`<div class="form-inline">`,`<a href="javascript:void(0)" class="btn-group-modify" data-id="${item.id}"><i class="fa fa-edit"></i></a> &nbsp;`,`<a href="javascript:void(0);" data-id="${item.id}" class="btn-group-delete"><i class="fa-solid fa-trash-can text-danger"></i></a>`,`</div>`].join('');}}];if(!mThis.table)
mThis.table=mThis.tblItems.DataTable({searching:false,destroy:true,paging:true,ordering:false,retrieve:true,info:true,pageLength:10,bLengthChange:false,saveState:true,'processing':true,'language':{'loadingRecords':'&nbsp;','processing':'Loading...',"emptyTable":LocaleManager.trans('No data to display','datatable')},'data':data,'columns':my_columns,"createdRow":function(row,data,dataIndex){cnt++;let tr=$(row);tr.data('id',data.id);}});if(typeof onFinish==='function')onFinish();});};this.show=(options=null)=>{if(!options)options={};mThis.options=options;mThis.prepareOptions(d=>{VSUtil.setComboItems(mThis.elFilter_category,d.categories,'id','category',true,'(All Categories)',0);VSUtil.setComboItems(mThis.elFilter_stock_class,d.stockclasses,'code','stock_class',true,'(All Classes)',0);mThis.displayItemGroups(options,()=>{main_view.setTitle(mThis.title_prop);mThis.self.show().siblings().hide();});});}}
let FilterDialog=new function(){let mThis=this;this.self=$('#_stk_dlgFilterStockTracking');this.btnSave=$('#_stk_dlgFilterStockTracking_btnOK');this.FilterWarehouse=$('#_stk_dlgFilterStockTracking_select_warehouse');this.FilterBlock=$('#_stk_dlgFilterStockTracking_select_block');this.FilterClass=$('#_stk_dlgFilterStockTracking_select_class');this.FilterCategory=$('#_stk_dlgFilterStockTracking_select_category');this.FilterGroup=$('#_stk_dlgFilterStockTracking_select_group');this.btnSave.on('click',function(e){e.preventDefault();let op={'warehouse':mThis.FilterWarehouse.val(),'block':mThis.FilterBlock.val(),'stock_class_id':mThis.FilterClass.val(),'category_id':mThis.FilterCategory.val(),'group_id':mThis.FilterGroup.val()};if(typeof mThis.onClose==='function')mThis.onClose(op);mThis.self.modal('hide');});this.show=(option)=>{if(!option)option={};mThis.onClose=option.onClose;mThis.self.modal({backdrop:'static'});}}
let ReceiveStokeDialog=new function(){let mThis=this;this.self=$('#_stk_dlgReceiveStock');this.elVendor=$('#_stk_select_vendors');this.btnSave=$('#_stk_dlgReceiveStock_btnSave');this.loadItems=(onFinish)=>{vsapi.call(`${main_view.base_url}/api/inventory/settings/receive-stock-options`,null).then((res)=>{if(res.status_code===200){let d=StringSanitizer.sanitizeObject(res.data);onFinish(d);}});}
mThis.columns=[{"name":"item_id","title":"Name","dataType":"string","displayType":"select","width":"250px",},{"name":"qty","title":"Qty","width":"100px","dataType":"number","displayType":"input",},{"name":"sku","title":"SKU","dataType":"string","displayType":"input","readOnly":true,},{"name":"stock_class","title":"Stock Class","dataType":"string","displayType":"select"},{"name":"price","title":"Price","dataType":"number","displayType":"input","currencySymbol":"$"},{"name":"discount","title":"Discount(%)","dataType":"number","displayType":"input","cssClass":""},{"name":"line_total","title":"Total","dataType":"number","currencySymbol":"$","readOnly":true}];this.cfg=new ItemsView('_stk_div_items_panel',{columns:mThis.columns,"validateColumns":{"name":"positive","qty":"positive","price":"positive"},"showColumnHeaders":true,"showAddLineButton":true,"onItemChange":(selOp,col_name,td)=>{let tr=td.parentNode;mThis.setTotal(col_name,tr);},"keyup":(e,col_name,td)=>{let tr=td.parentNode;mThis.setTotal(col_name,tr);},"onInputChange":(e,col_name,td)=>{let tr=td.parentNode;mThis.setTotal(col_name,tr);}});this.setTotal=(col_name,tr)=>{let d=mThis.cfg.getDataRow(tr);let cause_cols={'name':1,'qty':1,'price':1,'discount':1};let p={"id":d.item_id};vsapi.call(`${main_view.base_url}/api/inventory/item-info`,p).then(res=>{if(res.status_code===200){let item=StringSanitizer.sanitizeObject(res.data);mThis.cfg.setCellValue(tr,'sku',item.sku);mThis.cfg.setCellValue(tr,'price',item.cost);d.price=parseFloat(item.cost);if(cause_cols[col_name]){d.qty=parseFloat(d.qty);let total=(d.qty*d.price);d.discount=parseFloat(d.discount);let discount_amt=total*d.discount / 100;let net_total=total-discount_amt;mThis.cfg.setCellValue(tr,'line_total',net_total);}}});}
this.btnSave.on('click',function(e){e.preventDefault();let p=mThis.getFormData();mThis.self.modal('hide');});this.show=(option)=>{if(!option)option={};mThis.onClose=option.onClose;mThis.loadItems((d)=>{mThis.cfg.setSelectOptions("item_id",d.items);VSUtil.setComboItems(mThis.elVendor,d.vendors,'id','vendor_name',true,'(select vendor)',null);mThis.self.modal({backdrop:'static',});});}
this.getFormData=()=>{let p={};mThis.self.find('.data-input').each(function(){let el=$(this);let f=el.data('field');p[f]=el.val();});p.items=mThis.cfg.getItems();return p;}}
